1	package wallet
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7		"time"
8	)
9	
10	// 本文件为“同一使用账户 + 相同请求编号”的重复申请补充会话校验回归保障：
11	// 幂等取回已有结果之前仍必须通过会话校验（会话属于该使用账户、绑定当前
12	// 设备且有效），不能因为请求已经受理就跳过；失效会话的重试只留下零金额
13	// 的申请拒绝记录，原请求、资金与策略累计一律不变；合法更换会话后重复
14	// 申请照常返回原请求，且不再次冻结费用、不追加账本记录。
15	
16	// reapplyClockBase 等为各场景共享的时间安排：申请在基刻受理，s1 在 1 小时
17	// 后到期，替代会话 s1b 与策略窗口都覆盖全部测试时刻（且关闭预留超时）。
18	var (
19		reapplySession1ExpiryOffset = time.Hour
20		reapplySession2ExpiryOffset = 4 * time.Hour
21		reapplyPolicyEndOffset      = 5 * time.Hour
22	)
23	
24	// setupReapplyReserved 构造一笔已成功预留费用的请求：
25	// 出资账户 payer（余额 1000），使用账户 u1，会话 s1（绑定 dev1）与替代
26	// 会话 s1b（绑定 dev1b），策略 p1 关闭审批与预留超时；在基刻以 s1 提交
27	// r1（预估 100）并直接预留，返回首次受理视图与可原样重放的申请内容。
28	func setupReapplyReserved(t *testing.T) (*Wallet, *clock, RequestInput, RequestView) {
29		t.Helper()
30		w, c := newTestWallet()
31		base := c.t
32		mustAccount(t, w, "payer", 1000)
33		mustAccount(t, w, "u1", 0)
34		if _, err := w.CreateSession("s1", "u1", "dev1", base.Add(reapplySession1ExpiryOffset)); err != nil {
35			t.Fatal(err)
36		}
37		if _, err := w.CreateSession("s1b", "u1", "dev1b", base.Add(reapplySession2ExpiryOffset)); err != nil {
38			t.Fatal(err)
39		}
40		p := PolicySpec{
41			ID:                "p1",
42			PayerAccountID:    "payer",
43			AllowedAccountIDs: []string{"u1"},
44			Operation:         "charge",
45			Payee:             "shop",
46			StartsAt:          base.Add(-time.Hour),
47			EndsAt:            base.Add(reapplyPolicyEndOffset),
48			MaxPerRequest:     100,
49			MaxTotal:          1000,
50		}
51		if err := w.SavePolicy(p); err != nil {
52			t.Fatal(err)
53		}
54		in := RequestInput{
55			PolicyID:     "p1",
56			RequestID:    "r1",
57			AccountID:    "u1",
58			SessionID:    "s1",
59			DeviceID:     "dev1",
60			Operation:    "charge",
61			Payee:        "shop",
62			EstimatedFee: 100,
63		}
64		first, err := w.Apply(in)
65		if err != nil {
66			t.Fatal(err)
67		}
68		if first.State != RequestReserved {
69			t.Fatalf("setup: first state = %v, want reserved", first.State)
70		}
71		return w, c, in, first
72	}
73	
74	// countRequestEntries 统计关联指定请求的某类账本记录条数。
75	func countRequestEntries(entries []LedgerEntry, kind LedgerKind, requestID string) int {
76		n := 0
77		for _, e := range entries {
78			if e.Kind == kind && e.RequestID == requestID {
79				n++
80			}
81		}
82		return n
83	}
84	
85	// latestRejection 返回指定请求最后一条申请拒绝记录。
86	func latestRejection(entries []LedgerEntry, requestID string) (LedgerEntry, bool) {
87		var found LedgerEntry
88		ok := false
89		for _, e := range entries {
90			if e.Kind == LedgerRejection && e.RequestID == requestID {
91				found, ok = e, true
92			}
93		}
94		return found, ok
95	}
96	
97	// assertReservedRequestUnchanged 断言原已预留请求没有被失败的重复申请改写：
98	// 状态仍是已预留、受理/预留时刻与预估费用不变、不携带任何拒绝或审批决定；
99	// 出资账户余额与策略预留/已花费累计也保持调用方给定的快照。
100	func assertReservedRequestUnchanged(t *testing.T, w *Wallet, first RequestView, wantBal Balances, wantReserved, wantSpent int64) {
101		t.Helper()
102		got, err := w.Request("u1", "r1")
103		if err != nil {
104			t.Fatal(err)
105		}
106		if got.State != RequestReserved {
107			t.Fatalf("original request state = %v, want still reserved (the failed call must not reject the original request)", got.State)
108		}
109		if !got.CreatedAt.Equal(first.CreatedAt) {
110			t.Fatalf("created at changed: %v, want %v", got.CreatedAt, first.CreatedAt)
111		}
112		if !got.ReservedAt.Equal(first.ReservedAt) {
113			t.Fatalf("reserved at changed: %v, want %v", got.ReservedAt, first.ReservedAt)
114		}
115		if !got.ReserveDeadline.Equal(first.ReserveDeadline) || got.ReserveDuration != first.ReserveDuration {
116			t.Fatalf("reserve timing changed: deadline %v/%v duration %v/%v",
117				got.ReserveDeadline, first.ReserveDeadline, got.ReserveDuration, first.ReserveDuration)
118		}
119		if got.EstimatedFee != first.EstimatedFee || got.EstimatedFee != 100 {
120			t.Fatalf("estimated fee changed: %d, want %d", got.EstimatedFee, first.EstimatedFee)
121		}
122		if got.ActualFee != 0 {
123			t.Fatalf("failed re-apply must not settle: actual fee = %d", got.ActualFee)
124		}
125		if got.RejectReason != "" || got.ApproverAccountID != "" || !got.DecidedAt.IsZero() {
126			t.Fatalf("original request carries decision fields from the failed call: reason %q approver %q decided %v",
127				got.RejectReason, got.ApproverAccountID, got.DecidedAt)
128		}
129		if bal, _ := w.Balance("payer"); bal != wantBal {
130			t.Fatalf("payer balance = %+v, want %+v", bal, wantBal)
131		}
132		if pv, _ := w.Policy("p1"); pv.ReservedTotal != wantReserved || pv.SpentTotal != wantSpent {
133			t.Fatalf("policy totals = reserved %d spent %d, want %d/%d",
134				pv.ReservedTotal, pv.SpentTotal, wantReserved, wantSpent)
135		}
136	}
137	
138	// assertOnlyRejectionAppended 断言失败的重复申请只新增了一条零金额申请拒绝
139	// 记录（关联本次使用账户与请求编号、原因含会话失败说明、时间为当前时刻），
140	// 原有资金记录（一条全额预留）保留且没有新增任何退款、扣减或预留。
141	func assertOnlyRejectionAppended(t *testing.T, w *Wallet, ledgerLenBefore int, requestID, reasonPart string, at time.Time) {
142		t.Helper()
143		all := w.Ledger()
144		if len(all) != ledgerLenBefore+1 {
145			t.Fatalf("ledger entries = %d, want exactly one appended rejection (%d)", len(all), ledgerLenBefore+1)
146		}
147		rec, ok := latestRejection(all, requestID)
148		if !ok {
149			t.Fatal("missing zero-amount LedgerRejection for the failed duplicate apply")
150		}
151		if rec.AccountID != "u1" {
152			t.Fatalf("rejection account = %q, want using account u1", rec.AccountID)
153		}
154		if rec.Amount != 0 {
155			t.Fatalf("rejection amount = %d, want 0", rec.Amount)
156		}
157		if rec.PolicyID != "" {
158			t.Fatalf("application rejection must not carry policy id, got %q", rec.PolicyID)
159		}
160		if !strings.Contains(rec.Reason, reasonPart) {
161			t.Fatalf("rejection reason = %q, want it to mention %q", rec.Reason, reasonPart)
162		}
163		if !rec.At.Equal(at) {
164			t.Fatalf("rejection at %v, want %v", rec.At, at)
165		}
166		// 原预留保留；失败的重复申请不产生退款、扣减或第二条预留。
167		if n := countRequestEntries(all, LedgerReserve, requestID); n != 1 {
168			t.Fatalf("reserve entries = %d, want exactly the original one", n)
169		}
170		if n := countRequestEntries(all, LedgerSettle, requestID); n != 0 {
171			t.Fatalf("failed re-apply produced %d settle entries", n)
172		}
173		if n := countRequestEntries(all, LedgerRefund, requestID); n != 0 {
174			t.Fatalf("failed re-apply produced %d refund entries", n)
175		}
176		if e, ok := ledgerEntryFor(all, LedgerReserve, requestID); !ok || e.Amount != 100 || e.AccountID != "payer" {
177			t.Fatalf("original reserve entry altered: %+v ok=%v", e, ok)
178		}
179	}
180	
181	// TestDuplicateApplyRevokedSessionRejected：申请会话被吊销后，用原会话提交
182	// 相同申请必须返回会话已吊销错误，而不是取回已预留结果。
183	func TestDuplicateApplyRevokedSessionRejected(t *testing.T) {
184		w, c, in, first := setupReapplyReserved(t)
185	
186		c.t = c.t.Add(5 * time.Minute)
187		if err := w.RevokeSession("s1"); err != nil {
188			t.Fatal(err)
189		}
190		before := len(w.Ledger())
191	
192		replay, err := w.Apply(in)
193		if !errors.Is(err, ErrSessionRevoked) {
194			t.Fatalf("re-apply on revoked session err = %v, want ErrSessionRevoked", err)
195		}
196		if replay.State != 0 || replay.RequestID != "" {
197			t.Fatalf("failed call must not return a request view: %+v", replay)
198		}
199	
200		// 原请求仍是已预留，资金与策略累计不变（可用 900 / 预留 100）。
201		assertReservedRequestUnchanged(t, w, first, Balances{Available: 900, Reserved: 100}, 100, 0)
202		// 只留下一条说明会话已吊销的零金额拒绝记录。
203		assertOnlyRejectionAppended(t, w, before, "r1", "revoked", c.t)
204	
205		// 原请求继续存在并可正常结算：本次调用被拒绝不等于原请求被拒绝。
206		if settled, err := w.Settle("u1", "r1", 100); err != nil || settled.State != RequestSettled {
207			t.Fatalf("original reserved request should still settle after rejected replay: %+v %v", settled, err)
208		}
209	}
210	
211	// TestDuplicateApplyExpiredSessionRejected：会话自然到期后，相同操作返回会话
212	// 已过期错误；到期时刻本身也算过期。
213	func TestDuplicateApplyExpiredSessionRejected(t *testing.T) {
214		for _, tc := range []struct {
215			name   string
216			offset time.Duration
217		}{
218			{"exactly at expiry", time.Hour},
219			{"after expiry", time.Hour + 5*time.Minute},
220		} {
221			t.Run(tc.name, func(t *testing.T) {
222				w, c, in, first := setupReapplyReserved(t)
223				c.t = c.t.Add(tc.offset)
224				before := len(w.Ledger())
225	
226				replay, err := w.Apply(in)
227				if !errors.Is(err, ErrSessionExpired) {
228					t.Fatalf("re-apply on expired session err = %v, want ErrSessionExpired", err)
229				}
230				if replay.RequestID != "" {
231					t.Fatalf("failed call must not return a request view: %+v", replay)
232				}
233	
234				assertReservedRequestUnchanged(t, w, first, Balances{Available: 900, Reserved: 100}, 100, 0)
235				assertOnlyRejectionAppended(t, w, before, "r1", "expired", c.t)
236			})
237		}
238	}
239	
240	// TestDuplicateApplyRevokedAndExpiredReportsRevoked：会话同时已吊销和已到期
241	// 时，仍按现有校验顺序报告已吊销，而不是已过期。
242	func TestDuplicateApplyRevokedAndExpiredReportsRevoked(t *testing.T) {
243		w, c, in, first := setupReapplyReserved(t)
244	
245		// 先越过到期时刻，再吊销已到期的会话（吊销允许作用于已到期会话）。
246		c.t = c.t.Add(reapplySession1ExpiryOffset + 5*time.Minute)
247		if err := w.RevokeSession("s1"); err != nil {
248			t.Fatal(err)
249		}
250		before := len(w.Ledger())
251	
252		_, err := w.Apply(in)
253		if !errors.Is(err, ErrSessionRevoked) {
254			t.Fatalf("err = %v, want ErrSessionRevoked to take precedence", err)
255		}
256		if errors.Is(err, ErrSessionExpired) {
257			t.Fatalf("revoked+expired session must report revoked, got expired: %v", err)
258		}
259	
260		assertReservedRequestUnchanged(t, w, first, Balances{Available: 900, Reserved: 100}, 100, 0)
261		assertOnlyRejectionAppended(t, w, before, "r1", "revoked", c.t)
262	}
263	
264	// TestDuplicateApplyValidReplacementSessionReturnsOriginal：同一使用账户换用
265	// 另一条绑定其他设备的有效会话、设备随之更改，其余内容一致时，重复提交
266	// 必须返回原请求：不因会话编号不同报内容冲突，首次受理信息不变，不再次
267	// 冻结费用、不追加账本记录。
268	func TestDuplicateApplyValidReplacementSessionReturnsOriginal(t *testing.T) {
269		w, c, in, first := setupReapplyReserved(t)
270		c.t = c.t.Add(10 * time.Minute)
271		before := len(w.Ledger())
272	
273		replay := in
274		replay.SessionID = "s1b"
275		replay.DeviceID = "dev1b"
276		got, err := w.Apply(replay)
277		if err != nil {
278			t.Fatalf("re-apply with a different valid session must return original: %v", err)
279		}
280		if got.RequestID != "r1" || got.State != RequestReserved {
281			t.Fatalf("replay result = %+v, want original reserved request", got)
282		}
283		// 首次受理信息（提交时间、预留时刻、预估费用）保持不变。
284		if !got.CreatedAt.Equal(first.CreatedAt) || !got.ReservedAt.Equal(first.ReservedAt) {
285			t.Fatalf("acceptance info changed: created %v/%v reserved %v/%v",
286				got.CreatedAt, first.CreatedAt, got.ReservedAt, first.ReservedAt)
287		}
288		if got.EstimatedFee != 100 {
289			t.Fatalf("estimated fee = %d, want 100", got.EstimatedFee)
290		}
291		// 不再次冻结费用：余额与策略累计与首次受理后一致。
292		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 900, Reserved: 100}) {
293			t.Fatalf("balance = %+v, want {900 100}", bal)
294		}
295		if pv, _ := w.Policy("p1"); pv.ReservedTotal != 100 || pv.SpentTotal != 0 {
296			t.Fatalf("policy totals = reserved %d spent %d, want 100/0", pv.ReservedTotal, pv.SpentTotal)
297		}
298		// 不追加任何账本记录（连零金额状态记录也没有）。
299		if len(w.Ledger()) != before {
300			t.Fatalf("ledger entries changed on valid idempotent re-apply: %d -> %d", before, len(w.Ledger()))
301		}
302	
303		// 通过会话校验后若预估费用与原申请不同，仍返回原有冲突错误：不能覆盖
304		// 原请求，也不能再次预留。
305		conflict := replay
306		conflict.EstimatedFee = 90
307		if _, err := w.Apply(conflict); !errors.Is(err, ErrConflict) {
308			t.Fatalf("different fee on valid session err = %v, want ErrConflict", err)
309		}
310		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 900, Reserved: 100}) {
311			t.Fatalf("balance changed after conflicting re-apply: %+v", bal)
312		}
313		if pv, _ := w.Policy("p1"); pv.ReservedTotal != 100 || pv.SpentTotal != 0 {
314			t.Fatalf("policy totals changed after conflict: reserved %d spent %d", pv.ReservedTotal, pv.SpentTotal)
315		}
316		if len(w.Ledger()) != before {
317			t.Fatalf("conflicting re-apply appended ledger entries: %d -> %d", before, len(w.Ledger()))
318		}
319		cur, _ := w.Request("u1", "r1")
320		if cur.State != RequestReserved || cur.EstimatedFee != 100 || !cur.CreatedAt.Equal(first.CreatedAt) {
321			t.Fatalf("original request overwritten by conflicting re-apply: %+v", cur)
322		}
323	}
324	
325	// setupReapplySettled 在已预留场景上把 r1 按实际费用 60 结算，返回受理视图
326	// 与结算视图。结算后 payer 可用 940 / 预留 0，策略预留 0 / 已花费 60。
327	func setupReapplySettled(t *testing.T) (*Wallet, *clock, RequestInput, RequestView, RequestView) {
328		t.Helper()
329		w, c, in, first := setupReapplyReserved(t)
330		c.t = c.t.Add(5 * time.Minute)
331		settledAt := c.t
332		settled, err := w.Settle("u1", "r1", 60)
333		if err != nil {
334			t.Fatal(err)
335		}
336		if !settled.SettledAt.Equal(settledAt) {
337			t.Fatalf("setup: settled at %v, want %v", settled.SettledAt, settledAt)
338		}
339		return w, c, in, first, settled
340	}
341	
342	// TestDuplicateApplySettledRequestSessionRules：已经结算的请求遵守同一会话
343	// 规则——失效会话重试仍被拒绝（只留零金额拒绝记录，结算结果与资金不变）；
344	// 有效替代会话重试返回原已结算结果，实际费用与结算时间保持不变；通过会话
345	// 校验后费用不同仍报冲突，不覆盖、不再次预留。
346	func TestDuplicateApplySettledRequestSessionRules(t *testing.T) {
347		t.Run("revoked session rejected, settlement untouched", func(t *testing.T) {
348			w, c, in, first, settled := setupReapplySettled(t)
349			c.t = c.t.Add(10 * time.Minute)
350			if err := w.RevokeSession("s1"); err != nil {
351				t.Fatal(err)
352			}
353			ledgerBefore := len(w.Ledger())
354	
355			if _, err := w.Apply(in); !errors.Is(err, ErrSessionRevoked) {
356				t.Fatalf("re-apply settled request on revoked session err = %v, want ErrSessionRevoked", err)
357			}
358			// 只新增一条零金额拒绝记录，资金账本（预留、扣减、差额退回）原样保留。
359			all := w.Ledger()
360			if len(all) != ledgerBefore+1 {
361				t.Fatalf("ledger entries = %d, want one rejection appended", len(all))
362			}
363			rec, ok := latestRejection(all, "r1")
364			if !ok || rec.AccountID != "u1" || rec.Amount != 0 || !strings.Contains(rec.Reason, "revoked") {
365				t.Fatalf("rejection entry wrong: %+v ok=%v", rec, ok)
366			}
367			if n := countRequestEntries(all, LedgerReserve, "r1"); n != 1 {
368				t.Fatalf("reserve entries = %d, want 1", n)
369			}
370			if n := countRequestEntries(all, LedgerSettle, "r1"); n != 1 {
371				t.Fatalf("settle entries = %d, want the original single settlement", n)
372			}
373			if n := countRequestEntries(all, LedgerRefund, "r1"); n != 1 {
374				t.Fatalf("refund entries = %d, want the original change refund", n)
375			}
376			// 结算结果不变：实际费用与结算时间保持，余额与策略累计不变。
377			assertSettledRequestStays(t, w, first, settled)
378		})
379	
380		t.Run("expired session rejected", func(t *testing.T) {
381			w, c, in, first, settled := setupReapplySettled(t)
382			c.t = c.t.Add(reapplySession1ExpiryOffset - 5*time.Minute) // 结算在 T+5m，此刻为会话到期时刻 T+1h
383			ledgerBefore := len(w.Ledger())
384	
385			if _, err := w.Apply(in); !errors.Is(err, ErrSessionExpired) {
386				t.Fatalf("re-apply settled request on expired session err = %v, want ErrSessionExpired", err)
387			}
388			if len(w.Ledger()) != ledgerBefore+1 {
389				t.Fatalf("ledger entries = %d, want one rejection appended", len(w.Ledger()))
390			}
391			assertSettledRequestStays(t, w, first, settled)
392		})
393	
394		t.Run("valid replacement session returns settled result", func(t *testing.T) {
395			w, c, in, first, settled := setupReapplySettled(t)
396			c.t = c.t.Add(10 * time.Minute)
397			ledgerBefore := len(w.Ledger())
398	
399			replay := in
400			replay.SessionID = "s1b"
401			replay.DeviceID = "dev1b"
402			got, err := w.Apply(replay)
403			if err != nil {
404				t.Fatalf("valid replacement session should return settled result: %v", err)
405			}
406			if got.State != RequestSettled || got.ActualFee != 60 || !got.SettledAt.Equal(settled.SettledAt) {
407				t.Fatalf("replay result = %+v, want original settled result actual 60 at %v", got, settled.SettledAt)
408			}
409			if !got.CreatedAt.Equal(first.CreatedAt) {
410				t.Fatalf("created at changed: %v, want %v", got.CreatedAt, first.CreatedAt)
411			}
412			// 不追加账本记录、不再次冻结或扣款。
413			if len(w.Ledger()) != ledgerBefore {
414				t.Fatalf("ledger entries changed on idempotent settled re-apply: %d -> %d", ledgerBefore, len(w.Ledger()))
415			}
416			if bal, _ := w.Balance("payer"); bal != (Balances{Available: 940, Reserved: 0}) {
417				t.Fatalf("balance = %+v, want {940 0}", bal)
418			}
419			if pv, _ := w.Policy("p1"); pv.ReservedTotal != 0 || pv.SpentTotal != 60 {
420				t.Fatalf("policy totals = reserved %d spent %d, want 0/60", pv.ReservedTotal, pv.SpentTotal)
421			}
422	
423			// 通过会话校验后费用不同：仍是原有冲突错误，结算结果不被覆盖。
424			conflict := replay
425			conflict.EstimatedFee = 40
426			if _, err := w.Apply(conflict); !errors.Is(err, ErrConflict) {
427				t.Fatalf("different fee err = %v, want ErrConflict", err)
428			}
429			assertSettledRequestStays(t, w, first, settled)
430			if len(w.Ledger()) != ledgerBefore {
431				t.Fatalf("conflicting settled re-apply appended ledger entries: %d -> %d", ledgerBefore, len(w.Ledger()))
432			}
433		})
434	}
435	
436	// assertSettledRequestStays 复核已结算请求的实际费用、结算时间与资金快照。
437	func assertSettledRequestStays(t *testing.T, w *Wallet, first, settled RequestView) {
438		t.Helper()
439		got, err := w.Request("u1", "r1")
440		if err != nil {
441			t.Fatal(err)
442		}
443		if got.State != RequestSettled || got.ActualFee != 60 || !got.SettledAt.Equal(settled.SettledAt) {
444			t.Fatalf("settled result rewritten: %+v, want actual 60 at %v", got, settled.SettledAt)
445		}
446		if !got.CreatedAt.Equal(first.CreatedAt) || got.EstimatedFee != 100 {
447			t.Fatalf("acceptance info changed: %+v", got)
448		}
449		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 940, Reserved: 0}) {
450			t.Fatalf("balance = %+v, want {940 0}", bal)
451		}
452		if pv, _ := w.Policy("p1"); pv.ReservedTotal != 0 || pv.SpentTotal != 60 {
453			t.Fatalf("policy totals = reserved %d spent %d, want 0/60", pv.ReservedTotal, pv.SpentTotal)
454		}
455	}
