623		if !req.WaitDeadline.Equal(c.t.Add(30 * time.Second)) {
624			t.Fatalf("deadline = %v, want policy end %v", req.WaitDeadline, c.t.Add(30*time.Second))
625		}
626	
627		// 场景 2：会话到期早于等待时长 → 期限取会话到期。
628		w2, c2 := setupApproval(t)
629		sessExp := c2.t.Add(20 * time.Second)
630		if _, err := w2.CreateSession("s-short", "u1", "dev1", sessExp); err != nil {
631			t.Fatal(err)
632		}
633		in2 := approvalApply()
634		in2.SessionID = "s-short"
635		in2.RequestID = "rs"
636		req2, err := w2.Apply(in2)
637		if err != nil {
638			t.Fatal(err)
639		}
640		if !req2.WaitDeadline.Equal(sessExp) {
641			t.Fatalf("deadline = %v, want session expiry %v", req2.WaitDeadline, sessExp)
642		}
643	}
